/**
 * 浏览器端入口
 * - 导入全局样式
 * - 用自实现 AuthProvider 包裹整个应用（主站客户登录态）
 *
 * 🔴 browser 与 ssr 的 wrapRootElement 必须保持一致，否则 hydration 不匹配。
 *    这里刻意让 Provider **不接受任何配置 props**（clientId / redirectUri 等在
 *    `src/auth/AuthProvider.js` 内固定），进一步消除两处写法漂移的可能。
 *
 * @author 恒哥
 */
import React from 'react';
import { AuthProvider } from './src/auth/AuthProvider';
import { captureSourceParams, getConsent, GA_MEASUREMENT_ID } from './src/utils/analytics';
import './src/styles/global.css';

export const wrapRootElement = ({ element }) => (
  <AuthProvider>{element}</AuthProvider>
);

/**
 * 客户端启动时做两件事（都是幂等、纯浏览器侧）：
 * 1. 捕获来源参数（utm_* / gclid 等）—— 必须在用户点任何 CTA 之前完成，
 *    否则 install 页读不到，来源就断在第一跳。
 * 2. 若此前已同意过，把同意状态补交给 gtag。
 *    ⚠️ 静态 HTML 里的 default 是 denied，每次刷新都要重新 update 成 granted，
 *    否则用户同意过一次后刷新就又开始被拒。
 */
export const onClientEntry = () => {
  captureSourceParams();

  if (!GA_MEASUREMENT_ID) return;
  const consent = getConsent();
  if (consent !== 'granted' || typeof window.gtag !== 'function') return;
  window.gtag('consent', 'update', {
    analytics_storage: 'granted',
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
  });
};
