/**
 * Whaleal Cart 英文介绍图（与演示视频同叙事：1600×900）
 * 素材源：logo/card/ ；运行时：static/images/cards/
 *
 * 性能口径（2026-10-04）：
 * - 原始 PNG 单张 ≈ 1 MB，首页轮播 5 张合计 5.2 MB，是首屏卡顿主因
 * - 已全部转 AVIF（480/960/1600 三档）+ JPEG(960) fallback，单张 960w ≈ 24 KB
 * - `avif` 字段直接是 srcset 字符串；`fallback` 给不支持 AVIF 的老浏览器
 * - 重新生成图片的脚本：sharp resize + avif quality 62 / jpeg quality 78
 *
 * @author 恒哥
 */
/**
 * 产品展示卡（首页轮播 / 恢复邮件页画廊共用）
 * @param {string} base 图片 base 路径（不含扩展名）
 * @param {string} id 稳定标识，供 React key 与页面按语义筛选（勿随意改名）
 * @param {string} title 主标题
 * @param {string} caption 副标题
 */
const cartCard = (base, id, title, caption) => ({
  id,
  base,
  fallback: `${base}-960.jpg`,
  avif: [480, 960, 1600].map((w) => `${base}-${w}.avif ${w}w`).join(', '),
  title,
  caption,
});

